@namespace sv_3f5a75a6a35f46fbb8f1d2c9713c4455.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image-placeholder" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-card-body">
        <h5 class="product-name">@Product.Name</h5>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <div class="product-rating" aria-label="@($"Rating: {RoundedRating} out of 5")">
            @for (int i = 1; i <= 5; i++)
            {
                @(i <= RoundedRating ? "★" : "☆")
            }
        </div>
        @if (!Product.InStock)
        {
            <span class="badge out-of-stock-badge">Out of Stock</span>
        }
        <button class="btn btn-primary add-to-cart-btn"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private int RoundedRating => (int)Math.Round(Product.Rating);

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }
}

@namespace sv_3f5a75a6a35f46fbb8f1d2c9713c4455.Components.Pages.Catalog

@if (Products is null || Products.Count == 0)
{
    <div class="empty-results">
        <p>No products found matching your criteria.</p>
    </div>
}
else
{
    <div class="product-grid">
        @foreach (var product in Products)
        {
            <ProductCard Product="product"
                         OnSelected="OnProductSelected"
                         OnAddToCart="OnAddToCart" />
        }
    </div>
}

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = new();

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@namespace sv_3f5a75a6a35f46fbb8f1d2c9713c4455.Components.Pages.Catalog

<aside class="catalog-sidebar">
    <h4>Filters</h4>

    <div class="filter-section">
        <h5>Categories</h5>
        @if (Categories is not null)
        {
            @foreach (var category in Categories)
            {
                <label class="filter-checkbox">
                    <input type="checkbox"
                           checked="@IsSelected(category)"
                           @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                    @category
                </label>
            }
        }
    </div>

    <div class="filter-section">
        <h5>Price Range</h5>
        <div class="price-inputs">
            <input type="number" placeholder="Min" step="0.01" min="0"
                   value="@_minPrice"
                   @onchange="@(e => _minPrice = ParseDecimal(e.Value))" />
            <span>–</span>
            <input type="number" placeholder="Max" step="0.01" min="0"
                   value="@_maxPrice"
                   @onchange="@(e => _maxPrice = ParseDecimal(e.Value))" />
        </div>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox" @bind="_inStockOnly" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter]
    public List<string>? Categories { get; set; }

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !_selectedCategories.Contains(category))
            _selectedCategories.Add(category);
        else if (!isChecked)
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_3f5a75a6a35f46fbb8f1d2c9713c4455.Components.Pages.Catalog

<div class="catalog-toolbar">
    <div class="toolbar-sort">
        <label for="sort-select">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <div class="toolbar-info">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_3f5a75a6a35f46fbb8f1d2c9713c4455.Components.Pages.Catalog

@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="btn btn-outline"
                disabled="@(CurrentPage <= 1)"
                @onclick="() => GoToPage(CurrentPage - 1)">
            Previous
        </button>

        @for (int i = 1; i <= TotalPages; i++)
        {
            var pageNum = i;
            <button class="btn @(pageNum == CurrentPage ? "btn-primary" : "btn-outline")"
                    @onclick="() => GoToPage(pageNum)">
                @pageNum
            </button>
        }

        <button class="btn btn-outline"
                disabled="@(CurrentPage >= TotalPages)"
                @onclick="() => GoToPage(CurrentPage + 1)">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 1;

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

@page "/catalog"
@namespace sv_3f5a75a6a35f46fbb8f1d2c9713c4455.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogSidebar Categories="_categories"
                    OnFilterApplied="HandleFilterApplied"
                    OnFilterCleared="HandleFilterCleared" />

    <main class="catalog-main">
        @if (_error is not null)
        {
            <div class="alert alert-error">
                <p>Something went wrong: @_error</p>
                <button class="btn btn-secondary" @onclick="LoadProducts">Retry</button>
            </div>
        }
        else if (_loading)
        {
            <div class="loading-indicator">
                <p>Loading products...</p>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="_totalCount"
                            Page="_currentPage"
                            PageSize="PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="_products"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="_currentPage"
                               TotalCount="_totalCount"
                               PageSize="PageSize"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    private const int PageSize = 12;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? _categories;
    private List<Product> _products = new();
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _totalCount;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = categoriesTask.Result;
            ApplyResult(productsTask.Result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            var result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
            ApplyResult(result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyResult(PagedResult<Product> result)
    {
        _products = result.Items;
        _totalCount = result.TotalCount;
        _currentPage = result.Page;
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Add to cart logic would go here
        return Task.CompletedTask;
    }
}

